// wireSchema holds one operation's merged input and output documents.
type wireSchema struct {
	Input  string
	Output string
}

// wireSchemas merges every owned operation body with the shared $defs
// document.
var wireSchemas = map[string]wireSchema{
	"_effects.callback.evidence":      {Input: `{"type":"object","additionalProperties":false,"properties":{"operation_id":{"type":"string","format":"uuid"},"attempt_id":{"type":"string","format":"uuid"}},"required":["operation_id","attempt_id"]}`, Output: `{"type":"object","additionalProperties":false,"properties":{"action":{"$ref":"#/$defs/Action"},"observation":{"$ref":"#/$defs/Observation"},"generation":{"type":"integer","minimum":1,"maximum":9223372036854775807}},"required":["action","observation","generation"]}`},
	"_effects.admit":                  {schemaAdmitIn, schemaAdmitOut},
	"_effects.claim":                  {schemaClaimIn, schemaClaimOut},
	"_effects.pending":                {schemaPendingIn, schemaPendingOut},
	"_effects.prepare":                {schemaPrepareIn, schemaPrepareOut},
	"_effects.record":                 {schemaRecordIn, schemaRecordOut},
	"_effects.reconciliation.prepare": {schemaReconciliationPrepareIn, schemaReconciliationPrepareOut},
	"_effects.reconciliation.record":  {schemaReconciliationRecordIn, schemaReconciliationRecordOut},
	"_effects.restore.merge":          {schemaRestoreMergeIn, schemaRestoreMergeOut},
	"operation.compensation.propose":  {schemaCompensationIn, schemaCompensationOut},
	"operation.get":                   {schemaGetIn, schemaGetOut},
	"operation.list":                  {schemaListIn, schemaListOut},
	"operation.propose":               {schemaProposeIn, schemaProposeOut},
	"operation.reconcile":             {schemaReconcileIn, schemaReconcileOut},
	"operation.replacement.propose":   {schemaReplacementIn, schemaReplacementOut},
}

// mergeSchema splices an operation schema body into the shared $defs
// document, producing one schema document whose document-local $refs resolve
// against the exact brief definitions.
func mergeSchema(body string) (json.RawMessage, error) {
	if len(body) < 2 || body[0] != '{' || body[len(body)-1] != '}' {
		return nil, fmt.Errorf("schema body is not a JSON object")
	}
	defsLen := len(wireDefs)
	if defsLen < 2 || wireDefs[defsLen-1] != '}' {
		return nil, fmt.Errorf("embedded $defs document is malformed")
	}
	merged := wireDefs[:defsLen-1] + "," + body[1:]
	return json.RawMessage(merged), nil
}
